def solve(n, edges, start):
    import heapq
    graph=[[] for _ in range(n)]
    for u,v,w in edges: graph[u].append((v,w))
    dist=[None]*n; dist[start]=0; heap=[(0,start)]
    while heap:
        cost,u=heapq.heappop(heap)
        if cost!=dist[u]: continue
        for v,w in graph[u]:
            candidate=cost+w
            if dist[v] is None or candidate<dist[v]:
                dist[v]=candidate; heapq.heappush(heap,(candidate,v))
    return dist
